/*
   Problem 3. Configure output in open drain type and observe the differance.
 */

#include <stdio.h>
#include "led.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

void Init();
void Led_Toggle(uint8_t);

int main(void)
{
	Init();
	while(1)
	{
		Led_Toggle(GREEN);
				Led_Toggle(RED);
				DelayMs(1000);
				Led_Toggle(GREEN);
				DelayMs(1000);
				Led_Toggle(RED);
				DelayMs(1000);
				Led_Toggle(ORANGE);
				DelayMs(1000);
				Led_Toggle(BLUE);
				DelayMs(1000);
	}

}

void Init()
{
	RCC -> AHB1ENR |= BV(3);
	GPIOD -> MODER |= (BV(24) | BV(26) | BV(28) | BV(30) );
	GPIOD -> MODER &= ~(BV(25) | BV(27) | BV(29) | BV(31) );
	GPIOD -> OTYPER |= BV(12) | BV(13) | BV(14) | BV(15);
	GPIOD -> PUPDR &= ~(BV(24) | BV(25) | BV(26) | BV(27) | BV(28) | BV(29) | BV(30) |BV(31) );
	GPIOD -> OSPEEDR &= ~(BV(24) | BV(25) | BV(26) | BV(27) | BV(28) | BV(29) | BV(30) | BV(31) );
}

void Led_Toggle(uint8_t Pin)
{
	GPIOD -> ODR ^= BV(Pin);
}
